create table t_crawler_request
(
    id          int auto_increment
        primary key,
    url         varchar(511) null,
    gmt_create  timestamp    null,
    is_done     tinyint(1)   not null,
    error_count int          null comment '错误次数',
    constraint uk_url
        unique (url)
);

create index normal_isdone
    on t_crawler_request (is_done);

